def gen(rng):
    def fmt(n, k, a):
        return f'{n} {k}\n' + ' '.join(map(str, a))
    tests = [fmt(1, 1, [5]), fmt(1, 7, [-3]), fmt(4, 4, [1, 2, 3, 4]), fmt(5, 1, [3, 1, 4, 1, 5]), fmt(6, 3, [1, 2, 3, 4, 5, 6]), fmt(7, 10**9, list(range(7)))]
    for _ in range(40):
        n = rng.randint(1, 20)
        k = rng.choice([1, 2, 3, 4, 5, n, n + 1, rng.randint(1, 25)])
        tests.append(fmt(n, k, [rng.randint(-100, 100) for _ in range(n)]))
    n = 100000
    for k in (1, 7, 1000, 99999, 10**9):
        tests.append(fmt(n, k, [rng.randint(-10**9, 10**9) for _ in range(n)]))
    return tests
